package com.vandorlabs.neoforge.reservoir;
import com.mojang.serialization.MapCodec;import net.minecraft.core.*;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.*;import net.minecraft.world.item.context.BlockPlaceContext;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.level.block.state.*;import net.minecraft.world.level.block.state.properties.*;import net.minecraft.world.level.storage.loot.*;import net.minecraft.world.level.storage.loot.parameters.LootContextParams;import net.minecraft.world.phys.*;import java.util.List;
public final class NativeBufferBlock extends BaseEntityBlock {
 public static final DirectionProperty FACING=BlockStateProperties.FACING;public final boolean battery;
 public NativeBufferBlock(boolean battery,Properties p){super(p);this.battery=battery;registerDefaultState(stateDefinition.any().setValue(FACING,Direction.NORTH));}
 @Override protected MapCodec<? extends BaseEntityBlock> codec(){return MapCodec.unit(this);}@Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState> b){b.add(FACING);}
 @Override public BlockState getStateForPlacement(BlockPlaceContext c){return defaultBlockState().setValue(FACING,battery?com.vandorlabs.neoforge.NativeDirectionalPlacement.towardView(c):c.getClickedFace());}
 public BlockState legacyState(int meta){Direction face=battery?(meta==4?Direction.UP:meta==5?Direction.DOWN:Direction.from2DDataValue(meta)):Direction.from3DDataValue(meta&7);return defaultBlockState().setValue(FACING,face);}
 @Override public BlockEntity newBlockEntity(BlockPos pos,BlockState state){return battery?new NativeBatteryEntity(pos,state):new NativeHexTankEntity(pos,state);}
 @Override protected void neighborChanged(BlockState state,Level level,BlockPos pos,Block block,BlockPos from,boolean moving){if(!level.isClientSide&&level.getBlockEntity(pos) instanceof NativeBatteryEntity owner)owner.neighborChanged();}
 @Override protected boolean isSignalSource(BlockState state){return true;}
 @Override protected int getSignal(BlockState state,BlockGetter world,BlockPos pos,Direction side){
  return world.getBlockEntity(pos) instanceof NativeBufferEntity tile?tile.fullness().localPower():0;
 }
 @Override protected RenderShape getRenderShape(BlockState state){return RenderShape.ENTITYBLOCK_ANIMATED;}
 @Override public <T extends BlockEntity> BlockEntityTicker<T> getTicker(Level level,BlockState state,BlockEntityType<T> type){if(level.isClientSide)return null;return battery?createTickerHelper(type,NativeBufferBindings.BATTERY_ENTITY,NativeBatteryEntity::tick):createTickerHelper(type,NativeBufferBindings.TANK_ENTITY,(world,pos,s,tile)->tile.serverTick());}
 @Override protected InteractionResult useWithoutItem(BlockState state,Level level,BlockPos pos,Player player,BlockHitResult hit){return NativeBufferBindings.open(player,level,pos)?InteractionResult.sidedSuccess(level.isClientSide):InteractionResult.FAIL;}
 @Override protected ItemInteractionResult useItemOn(ItemStack stack,BlockState state,Level level,BlockPos pos,Player player,InteractionHand hand,BlockHitResult hit){if(hand!=InteractionHand.MAIN_HAND||stack.getItem() instanceof BlockItem)return ItemInteractionResult.PASS_TO_DEFAULT_BLOCK_INTERACTION;if(!battery&&level.getBlockEntity(pos) instanceof NativeHexTankEntity tank&&!tank.inert()&&com.vandorlabs.neoforge.NativeConfigurationAccess.canEditDialog(player,tank)&&net.neoforged.neoforge.fluids.FluidUtil.interactWithFluidHandler(player,hand,tank))return ItemInteractionResult.SUCCESS;return NativeBufferBindings.open(player,level,pos)?ItemInteractionResult.SUCCESS:ItemInteractionResult.FAIL;}
 @Override public ItemStack getCloneItemStack(BlockState state,HitResult hit,LevelReader level,BlockPos pos,Player player){return NativeBufferItem.pick(asItem(),level.getBlockEntity(pos),level.registryAccess());}
 @Override protected List<ItemStack> getDrops(BlockState state,LootParams.Builder context){return List.of(NativeBufferItem.pick(asItem(),context.getOptionalParameter(LootContextParams.BLOCK_ENTITY),context.getLevel().registryAccess()));}
 @Override public BlockState playerWillDestroy(Level level,BlockPos pos,BlockState state,Player player){if(!level.isClientSide&&level.getBlockEntity(pos) instanceof NativeBufferEntity owner)owner.forceRecovery(owner.inert()&&(player.isCreative()||!state.canHarvestBlock(level,pos,player)));return super.playerWillDestroy(level,pos,state,player);}
 @Override protected void onRemove(BlockState state,Level level,BlockPos pos,BlockState next,boolean moving){if(!battery&&(!state.is(next.getBlock())||state.getValue(FACING).getAxis()!=next.getValue(FACING).getAxis()))NativeTankGroups.invalidate(level);if(!state.is(next.getBlock())){if(!level.isClientSide&&!com.vandorlabs.neoforge.placement.NativeStationaryPlacement.mutating(level,pos)&&level.getBlockEntity(pos) instanceof NativeBufferEntity owner&&owner.inert()&&owner.takeRecovery())Block.popResource(level,pos,NativeBufferItem.pick(asItem(),owner,level.registryAccess()));}super.onRemove(state,level,pos,next,moving);}
 @Override protected BlockState rotate(BlockState s,Rotation r){return s.setValue(FACING,r.rotate(s.getValue(FACING)));}@Override protected BlockState mirror(BlockState s,Mirror m){return rotate(s,m.getRotation(s.getValue(FACING)));}
}
